        self.queue = []
        self.cache_dir = reader.library.path.parent / 'capas'
        self.cache_dir.mkdir(parents=True, exist_ok=True)
        reader.library.db.execute('CREATE TABLE IF NOT EXISTS cover_cache (path TEXT PRIMARY KEY, stamp TEXT, cover TEXT, error TEXT)')
        reader.library.db.commit()
        layout = QHBoxLayout(self)
        layout.setContentsMargins(0,0,0,0)
        layout.setSpacing(0)
        details = QWidget()
        details.setObjectName('libraryRail')
        details.setFixedWidth(248)
        side = QVBoxLayout(details)
