        pix = QPixmap()
        pix.loadFromData(base64.b64decode(BRAND_LOGO))
        logo.setPixmap(pix.scaled(180,150,Qt.AspectRatioMode.KeepAspectRatio,Qt.TransformationMode.SmoothTransformation))
        logo.setAlignment(Qt.AlignmentFlag.AlignCenter)
        side.addWidget(logo)
        self.preview = QLabel('Selecione um título')
        self.preview.setFixedSize(212,282)
        self.preview.setAlignment(Qt.AlignmentFlag.AlignCenter)
        self.title = QLabel('')
        self.title.setWordWrap(True)
        self.title.setAlignment(Qt.AlignmentFlag.AlignCenter)
        self.title.setStyleSheet('font-size:18px;font-weight:700;')
        self.progress = QLabel('')
        self.progress.setAlignment(Qt.AlignmentFlag.AlignCenter)
        self.progress.setStyleSheet('font-size:22px;font-weight:600;')
        self.open_button = QPushButton('Continuar leitura')
        self.open_button.clicked.connect(self.open_selected)
        for widget in (self.preview,self.title,self.progress,self.open_button):
            side.addWidget(widget)
        side.addStretch()
        self.folder_label = QLabel()
        self.folder_label.setWordWrap(True)
        side.addWidget(self.folder_label)
        layout.addWidget(details)
        right = QVBoxLayout()
        right.setContentsMargins(0,0,0,0)
        right.setSpacing(0)
        top = QWidget()
        top.setObjectName('libraryTop')
        nav = QHBoxLayout(top)
        file_menu = QMenu(self)
        file_menu.addAction('Abrir arquivo…',reader.choose_file)
        file_menu.addAction('Adicionar títulos…',self.import_files)
        file_menu.addSeparator()
        file_menu.addAction('Sair',reader.close)
        library_menu = QMenu(self)
        library_menu.addAction('Escolher pasta…',self.choose_folder)
        library_menu.addAction('Atualizar capas e títulos',self.manual_refresh)
        view_menu = QMenu(self)
        view_menu.addMenu(reader.brand_menu)
        view_menu.addAction('Tela cheia',lambda: reader.showNormal() if reader.isFullScreen() else reader.showFullScreen())
        for title, menu in [('Arquivo',file_menu),('Bibliotecas',library_menu),('Exibir',view_menu)]:
            button=QToolButton();button.setText(title);button.setMenu(menu)
            button.setPopupMode(QToolButton.ToolButtonPopupMode.InstantPopup)
            nav.addWidget(button)
        about=QToolButton();about.setText('Sobre')
        about.clicked.connect(lambda: QMessageBox.about(self,'Reader.ComiX','Reader.ComiX v09.1\nLeitura de quadrinhos, PDF e EPUB.\nBusca, anotações, PDF adaptável e OCR local.'))
        nav.addWidget(about);nav.addStretch()
        close=QToolButton();close.setText('×');close.setToolTip('Fechar programa');close.clicked.connect(reader.close)
        nav.addWidget(close)
        right.addWidget(top)
