        self.search.setPlaceholderText('Buscar título na biblioteca…')
        self.search.setClearButtonEnabled(True)
        self.search.textChanged.connect(self.populate)
        searchrow=QHBoxLayout();searchrow.setContentsMargins(28,14,28,6);searchrow.addWidget(self.search)
        right.addLayout(searchrow)
        self.grid=QListWidget()
        self.grid.setObjectName('coverGrid')
        self.grid.setViewMode(QListView.ViewMode.IconMode)
        self.grid.setResizeMode(QListView.ResizeMode.Adjust)
        self.grid.setMovement(QListView.Movement.Static)
        self.grid.setWrapping(True)
        self.grid.setGridSize(QSize(210,300))
        self.grid.setIconSize(QSize(180,240))
