        self.grid.currentItemChanged.connect(self.update_details)
        self.grid.itemActivated.connect(self.activate_item)
        self.grid.itemClicked.connect(lambda item:self.import_files() if item.data(Qt.ItemDataRole.UserRole) is None else None)
