    def toggle_reader_sidebar(self):
        visible=not self.reader_sidebar.isVisible()
        self.reader_sidebar.setVisible(visible)
        self.sidebar_toggle.setText('›' if visible else '‹')
        QTimer.singleShot(0,self.render)

    def schedule_reader_theme(self, *args):
        # O Qt atualiza a paleta após emitir colorSchemeChanged.
        QTimer.singleShot(0, self.apply_reader_theme)

    def refresh_page_colors(self):
        if not self.book:
            return
        if self.continuous:
            self.flow.cache.clear()
            self.flow.errors.clear()
            self.flow.loader.start(0)
            self.flow.viewport().update()
        else:
            vertical, horizontal = self.scroll.verticalScrollBar().value(), self.scroll.horizontalScrollBar().value()
            self.load_display()
            self.scroll.verticalScrollBar().setValue(vertical)
            self.scroll.horizontalScrollBar().setValue(horizontal)
        self.update_controls()

    def sync_reading_background(self):
        background = brand_colors()[0]
        foreground = '#f3f3f5'
        if isinstance(self.book, PdfReflowBook) and self.current_path:
            background, foreground, _ = reading_colors(self.library.appearance(self.current_path)[0])
        self.flow.canvas_background = background
        self.scroll.setStyleSheet(f'QScrollArea {{background:{background};border:0;}}')
        self.scroll.viewport().setStyleSheet(f'background:{background};')
        self.page.setStyleSheet(f'color:{foreground};background:{background};font-size:18px;')
        self.flow.viewport().update()

    def apply_reader_theme(self):
        if self.closed or getattr(self, '_reflowing', False):
            return
        palette = QApplication.palette()
        background = brand_colors()[0]
        foreground = '#f3f3f5'
        signature = background, foreground, brand_colors()[1]
        if getattr(self, '_reader_theme', None) != signature:
            self._reader_theme = signature
            self.setStyleSheet(interface_stylesheet())
            self.scroll.setStyleSheet(f'QScrollArea {{background:{background};border:0;}}')
            self.scroll.viewport().setStyleSheet(f'background:{background};')
            self.page.setStyleSheet(f'color:{foreground};background:{background};font-size:18px;')
            self.flow.viewport().update()
            dialog = getattr(self, '_appearance_dialog', None)
            if dialog:
                dialog.setStyleSheet(interface_stylesheet())
                self._appearance_preview_update()
        self.sync_reading_background()
        if isinstance(self.book, TEXT_BOOKS) and self.current_path:
            theme = self.library.appearance(self.current_path)[0]
            if theme == 'auto':
                colors = reading_colors(theme)
                if isinstance(self.book, EpubBook):
                    if self.book.set_theme(theme):
                        self.refresh_page_colors()
                elif getattr(self, '_fixed_page_colors', None) != colors:
                    self._fixed_page_colors = colors
                    self.refresh_page_colors()

    def changeEvent(self, event):
        super().changeEvent(event)
        if event.type() in (QEvent.Type.PaletteChange, QEvent.Type.ApplicationPaletteChange) and hasattr(self, 'reader_sidebar'):
            self.schedule_reader_theme()

    def seek_page(self, value):
        if not self.book:
            return
        index = max(0,min(len(self.book.pages)-1,value-1))
        if self.continuous:
            self.selection_popup.hide()
            self.selection = self.selection_start = None
            self.flow.jump(index,0,smooth=False)
            self.index, self.scroll_fraction = index, 0.0
            self.update_controls()
            self.save_progress()
        else:
            self.move(index-self.index)

    def show_home(self):
        if not hasattr(self,'home'):
            return
        self.save_progress()
        self.flow.detach()
        self.reset_pdf_state()
        if self.book:
            self.book.close()
        self.book = None
        self.current_path = None
        self.original = QPixmap()
        self.screens.setCurrentWidget(self.home)
        self.reading_bar.hide()
        self.menuBar().hide()
        self.dock.hide()
        self.annotations_dock.hide()
        self.setWindowTitle('Reader.ComiX v09.1 — Biblioteca')
        self.update_controls()
        self.home.rescan()
        self.home.poll.start()

